<fieldset><legend>Child details</legend>
    <div class="form-grid"><div><label for="first_name">First name</label><input id="first_name" name="first_name" value="{{ old('first_name', $child?->first_name) }}" autocomplete="given-name" required></div><div><label for="last_name">Last name</label><input id="last_name" name="last_name" value="{{ old('last_name', $child?->last_name) }}" autocomplete="family-name"></div></div>
    <div><label for="external_registration_number">External programme registration number (optional)</label><input id="external_registration_number" name="external_registration_number" value="{{ old('external_registration_number', $child?->external_registration_number) }}" maxlength="100"><span class="field-hint">Used only when duplicate detection is configured to compare external registration numbers.</span></div>
    <div class="form-grid"><div><label for="date_of_birth">Date of birth</label><input id="date_of_birth" name="date_of_birth" type="date" max="{{ today()->toDateString() }}" value="{{ old('date_of_birth', $child?->date_of_birth?->toDateString()) }}" required></div><div><label for="sex">Sex (if required by programme)</label><input id="sex" name="sex" value="{{ old('sex', $child?->sex) }}" maxlength="30" placeholder="Optional"></div></div>
    <div class="form-grid"><div><label for="locality">Area / locality</label><input id="locality" name="locality" value="{{ old('locality', $child?->locality) }}" autocomplete="address-level2"></div><div><label for="centre_id">Vaccination centre @if ($centres->isNotEmpty())<span class="required-indicator">Required</span>@else<span class="field-hint">Optional until a centre is configured</span>@endif</label><select id="centre_id" name="centre_id" @required($centres->isNotEmpty())><option value="">Select a centre</option>@foreach ($centres as $centre)<option value="{{ $centre->id }}" @selected((string) old('centre_id', $child?->centre_id) === (string) $centre->id)>{{ $centre->name }}</option>@endforeach</select></div></div>
    <div><label for="address">Address</label><textarea id="address" name="address" rows="2">{{ old('address', $child?->address) }}</textarea></div>
    <div><label for="internal_notes">Internal notes</label><textarea id="internal_notes" name="internal_notes" rows="2" placeholder="Administrative notes only">{{ old('internal_notes', $child?->internal_notes) }}</textarea></div>
    <div><label for="photograph">Child photograph (optional)</label><input id="photograph" type="file" name="photograph" accept="image/jpeg,image/png,image/webp"><span class="field-hint">JPG, PNG or WebP up to 2 MB. Stored privately.</span></div>
</fieldset>
